    };

    const vec2 = BlockVec(2).fromBytes(&input);
    const result_vec = vec2.invMixColumns();
    const result_bytes = result_vec.toBytes();

    for (0..2) |i| {
        const block = Block.fromBytes(input[i * 16 ..][0..16]);
        const expected = block.invMixColumns().toBytes();
