test window {
    {
        // moving average size 3
        var it = window(u8, "abcdefg", 3, 1);
        try testing.expectEqualSlices(u8, "abc", it.next().?);
        try testing.expectEqualSlices(u8, "bcd", it.next().?);
        try testing.expectEqualSlices(u8, "cde", it.next().?);
